323	 * who owe the most, ranked by what they still owe. For each client it sums the due across ALL of that
324	 * client's invoices (invoice -&gt; project -&gt; client), each invoice's due being its net total after
325	 * any discount/tax (the one-place {@link InvoiceMoney} rule) minus what has been paid against it — the
326	 * same money math as {@link ClientsOutstandingGetLogic}, worked out on the server so every surface
327	 * agrees. Only clients that owe something appear; the list is ordered by outstanding descending (ties
328	 * broken by client id for a stable order) and capped at five. Wired by
329	 * {@code officefloor/rest/api/dashboard/top-clients.GET.yml}.
330	 */
331	public class DashboardTopClientsGetLogic {
332	
333	    private static final int TOP_N = 5;
334	
335	    public void service(ClientRepository clients, ProjectRepository projects,
336	            InvoiceRepository invoices, PaymentRepository payments,
337	            ObjectResponse<List<TopClientView>> response) {
338	        // invoice -> project -> client: map each project to the client it belongs to.
339	        Map<Long, Long> projectToClient = projects.findAll().stream()
340	                .collect(Collectors.toMap(Project::getId, Project::getClientId));
341	        List<TopClientView> rows = clients.findAll().stream()
342	                .map(client -> {
343	                    BigDecimal outstanding = invoices.findAll().stream()
344	                            .filter(i -> client.getId().equals(projectToClient.get(i.getProjectId())))
345	                            .map(i -> {
346	                                BigDecimal paid = payments.findByInvoiceIdOrderByIdAsc(i.getId())
347	                                        .stream().map(Payment::getAmount)
348	                                        .reduce(BigDecimal.ZERO, BigDecimal::add);
349	                                BigDecimal netTotal = InvoiceMoney.netTotal(i.getAmount(),
350	                                        i.getDiscountPct(), i.getTaxPct());
351	                                return netTotal.subtract(paid);
352	                            })
353	                            .reduce(BigDecimal.ZERO, BigDecimal::add);
354	                    return new TopClientView(client.getId(), client.getName(), outstanding);
355	                })
356	                // Only clients that actually owe something are "top clients".
357	                .filter(row -> row.getOutstanding().compareTo(BigDecimal.ZERO) > 0)
358	                .sorted(Comparator.comparing(TopClientView::getOutstanding).reversed()
359	                        .thenComparing(TopClientView::getClientId))
360	                .limit(TOP_N)
361	                .collect(Collectors.toList());
362	        response.send(rows);
363	    }
364	
365	    /** One client in the ranking: who they are and how much they still owe. */
366	    public static class TopClientView {
367	        private final long clientId;
368	        private final String name;
369	        private final BigDecimal outstanding;
370	
371	        public TopClientView(long clientId, String name, BigDecimal outstanding) {
372	            this.clientId = clientId;
373	            this.name = name;
374	            this.outstanding = outstanding;
375	        }
