391	package net.officefloor.hq.app;
392	
393	import java.math.BigDecimal;
394	import java.util.ArrayList;
395	import java.util.Comparator;
396	import java.util.LinkedHashMap;
397	import java.util.List;
398	import java.util.Map;
399	import java.util.Set;
400	import java.util.stream.Collectors;
401	import org.springframework.web.bind.annotation.RequestParam;
402	import net.officefloor.web.ObjectResponse;
403	
404	/**
405	 * {@code GET /api/clients/statement?clientId=<id>} — a client's statement: every invoice across ALL
406	 * of that client's projects gathered in one place, each carrying how much is still due on it (its
407	 * amount minus what has been paid against it — the same money rule as {@link InvoiceDueGetLogic}),
408	 * and the OUTSTANDING TOTAL the client still owes (the sum of those dues). Derived on the server so
409	 * the money math lives in one place. Wired by {@code officefloor/rest/api/clients/statement.GET.yml}.
410	 */
411	public class ClientStatementGetLogic {
412	
413	    public void service(@RequestParam("clientId") Long clientId, ProjectRepository projects,
414	            InvoiceRepository invoices, PaymentRepository payments,
415	            ObjectResponse<ClientStatementView> response) {
416	        // The client's projects are the ones its invoices hang off (invoice -> project -> client).
417	        List<Project> clientProjects = projects.findAll().stream()
418	                .filter(p -> clientId.equals(p.getClientId()))
419	                .collect(Collectors.toList());
420	        Set<Long> projectIds = clientProjects.stream().map(Project::getId).collect(Collectors.toSet());
421	        Map<Long, String> projectNames = clientProjects.stream()
422	                .collect(Collectors.toMap(Project::getId, Project::getName));
423	        List<StatementInvoiceView> rows = invoices.findAll().stream()
424	                .filter(i -> projectIds.contains(i.getProjectId()))
425	                .sorted(Comparator.comparing(Invoice::getId))
426	                .map(i -> {
427	                    BigDecimal paid = payments.findByInvoiceIdOrderByIdAsc(i.getId()).stream()
428	                            .map(Payment::getAmount).reduce(BigDecimal.ZERO, BigDecimal::add);
429	                    // What is owed is the net total after any discount (Flyway V27), worked out the
430	                    // one-place way (InvoiceMoney) so the statement agrees with the dashboard and the
431	                    // invoice detail. The due — and the status derived from it — follow that total.
432	                    BigDecimal netTotal = InvoiceMoney.netTotal(i.getAmount(), i.getDiscountPct(),
433	                            i.getTaxPct());
434	                    BigDecimal due = netTotal.subtract(paid);
435	                    String status = InvoiceStatus.derive(i.getStatus(), netTotal, paid);
436	                    return new StatementInvoiceView(i.getId(), i.getProjectId(), netTotal,
437	                            paid, due, status);
438	                })
439	                .collect(Collectors.toList());
440	        BigDecimal outstanding = rows.stream().map(StatementInvoiceView::getDue)
441	                .reduce(BigDecimal.ZERO, BigDecimal::add);
442	        // Group the invoices under the job (project) they belong to, preserving invoice order within
443	        // each group and group order by first appearance, and carry each job's subtotal (the sum of
444	        // its invoices' dues). The subtotals sum back to the same outstanding total.
445	        Map<Long, StatementProjectView> byProject = new LinkedHashMap<>();
446	        for (StatementInvoiceView row : rows) {
447	            byProject.computeIfAbsent(row.getProjectId(), id -> new StatementProjectView(id,
448	                    projectNames.getOrDefault(id, ""))).add(row);
449	        }
450	        List<StatementProjectView> groups = new ArrayList<>(byProject.values());
451	        response.send(new ClientStatementView(clientId, rows, groups, outstanding));
452	    }
453	
454	    /** A client's statement: its invoices, grouped by job with subtotals, and the total still owed. */
455	    public static class ClientStatementView {
456	        private final long clientId;
457	        private final List<StatementInvoiceView> invoices;
458	        private final List<StatementProjectView> projects;
459	        private final BigDecimal outstandingTotal;
460	
461	        public ClientStatementView(long clientId, List<StatementInvoiceView> invoices,
462	                List<StatementProjectView> projects, BigDecimal outstandingTotal) {
463	            this.clientId = clientId;
464	            this.invoices = invoices;
465	            this.projects = projects;
466	            this.outstandingTotal = outstandingTotal;
467	        }
468	
469	        public long getClientId() {
470	            return clientId;
471	        }
472	
473	        public List<StatementInvoiceView> getInvoices() {
474	            return invoices;
475	        }
476	
477	        public List<StatementProjectView> getProjects() {
478	            return projects;
479	        }
480	
481	        public BigDecimal getOutstandingTotal() {
482	            return outstandingTotal;
483	        }
484	    }
485	
486	    /** One job (project) on the statement: its invoices and the subtotal still due across them. */
487	    public static class StatementProjectView {
488	        private final long projectId;
489	        private final String name;
490	        private final List<StatementInvoiceView> invoices = new ArrayList<>();
491	        private BigDecimal subtotal = BigDecimal.ZERO;
492	
493	        public StatementProjectView(long projectId, String name) {
494	            this.projectId = projectId;
495	            this.name = name;
496	        }
497	
498	        void add(StatementInvoiceView invoice) {
499	            this.invoices.add(invoice);
500	            this.subtotal = this.subtotal.add(invoice.getDue());
501	        }
502	
503	        public long getProjectId() {
504	            return projectId;
505	        }
506	
507	        public String getName() {
508	            return name;
509	        }
510	
511	        public List<StatementInvoiceView> getInvoices() {
512	            return invoices;
513	        }
514	
515	        public BigDecimal getSubtotal() {
516	            return subtotal;
517	        }
518	    }
519	
520	    /** One invoice on the statement: its amount, what has been paid, what is still due, and status. */
521	    public static class StatementInvoiceView {
522	        private final long id;
523	        private final long projectId;
524	        private final BigDecimal amount;
525	        private final BigDecimal paid;
526	        private final BigDecimal due;
527	        private final String status;
528	
529	        public StatementInvoiceView(long id, long projectId, BigDecimal amount, BigDecimal paid,
530	                BigDecimal due, String status) {
531	            this.id = id;
532	            this.projectId = projectId;
533	            this.amount = amount;
534	            this.paid = paid;
535	            this.due = due;
536	            this.status = status;
537	        }
538	
539	        public long getId() {
540	            return id;
541	        }
542	
543	        public long getProjectId() {
